{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table eggozdb.maplemonk.oms_ims_egg_movement as select tt.*, et.beat_date as et_date,et.transfer_egg_type,et.from_warehouse,et.to_warehouse, ifnull(sum(et.sent_eggs_ims),0)sent_eggs_ims, ifnull(sum(received_eggs_ims),0) received_eggs_ims, avg(oo.opening) opening, ifnull((ub.EGGS_SOLD_DAILY_TYPEWISE),0) EGGS_SOLD_DAILY_TYPEWISE from (select pp.grn_date,bbm.date beat_date, coalesce(pp.grn_date,bbm.date) common_date, pp.zone_name, coalesce(pp.egg_type,bbm.trail_egg_type) as egg_type_1, bbm.loading_point as beat_loading_point, pp.warehouse, coalesce(pp.warehouse,bbm.loading_point) common_point, ifnull(pp.processing_egg_count,0) processing_egg_count, ifnull(pp.procurement_egg_tray,0) procurement_egg_tray, ifnull(pp.total_packaging_loss,0) total_packaging_loss, ifnull(pp.total_processing_loss,0) total_processing_loss, ifnull(pp.total_procurement_loss,0) total_procurement_loss, ifnull(pp.eggqualitycheck_egg_loss,0) eggqualitycheck_egg_loss, sum(bbm.out_eggs) out_eggs,sum(bbm.sold_eggs)sold_eggs,sum(return_eggs) return_eggs, sum(replacement_eggs) replacement_eggs, sum(promo_eggs) promo_eggs from (select grn_date, zone_name,egg_type, processing_egg_count, warehouse,sum(procurement_egg_tray) procurement_egg_tray,sum(eggqualitycheck_egg_loss) eggqualitycheck_egg_loss, sum(total_packaging_loss)total_packaging_loss, sum(total_processing_loss) total_processing_loss,sum(total_procurement_loss) total_procurement_loss from eggozdb.maplemonk.batch_procurement_processing_packaging group by warehouse,grn_date,processing_egg_count,zone_name,egg_type ) pp full outer join (select date,name,loading_point,area, case when name in(\'White\',\'Nutra\') then \'White\' when name in(\'Free Range\',\'Brown\') then \'Brown\' else name end as trail_egg_type, sum(out_eggs) out_eggs ,sum(sold_eggs) sold_eggs, sum(return_eggs) return_eggs, sum(replacement_eggs) replacement_eggs, sum(promo_eggs) promo_eggs, from maplemonk.beat_material_kpi bm group by date,name,loading_point,area )bbm on pp.egg_type= bbm.trail_egg_type and pp.grn_date = bbm.date and pp.warehouse = bbm.loading_point group by pp.grn_date,bbm.date, beat_date, pp.zone_name,pp.egg_type,bbm.trail_egg_type , pp.processing_egg_count,pp.total_packaging_loss,pp.total_processing_loss,pp.total_procurement_loss,pp.warehouse,bbm.loading_point,pp.warehouse, pp.procurement_egg_tray,pp.eggqualitycheck_egg_loss )tt full outer join (select beat_date ,egg_type, to_warehouse,from_warehouse,sum(sent_eggs_ims) sent_eggs_ims,sum(received_eggs_ims) received_eggs_ims, case when egg_type in(\'White\',\'Nutra\') then \'White\' when egg_type in(\'Free Range\',\'Brown\') then \'Brown\' else egg_type end as transfer_egg_type from eggozdb.maplemonk.epc_dc_transfer group by beat_date,to_warehouse,egg_type,from_warehouse ) et on tt.warehouse=et.from_warehouse and tt.common_date = et.beat_date and tt.egg_type_1=et.transfer_egg_type left join (select warehouse,egg_type,month,year,sum(opening) opening from eggozdb.maplemonk.bi_opening group by warehouse,egg_type,month,year) oo on tt.common_point = oo.warehouse and tt.egg_type_1 = oo.egg_type and month(tt.common_date) = oo.month and year(tt.common_date) = oo.year left join (select delivery_date,region,category,procured_region, sum(eggs_sold_daily_typewise) ub_sold_eggs, sum(EGGS_SOLD_DAILY_TYPEWISE)EGGS_SOLD_DAILY_TYPEWISE, \'Karnal EPC\' Loading_point from ub_log group by region,delivery_date,category,procured_region )ub on tt.common_date = ub.delivery_date and tt.egg_type_1 = ub.category and tt.common_point = ub.loading_point group by grn_date, tt.beat_date,et.beat_date, zone_name,tt.egg_type_1,et.transfer_egg_type,et.to_warehouse,et.from_warehouse, processing_egg_count, procurement_egg_tray,TOTAL_PACKAGING_LOSS,TOTAL_PROCESSING_LOSS,TOTAL_PROCUREMENT_LOSS, eggqualitycheck_egg_loss,tt.beat_loading_point, tt.out_eggs,tt.sold_eggs,tt.return_eggs,tt.warehouse, tt.replacement_eggs,tt.replacement_eggs, tt.promo_eggs,tt.common_point,tt.common_date,ub.EGGS_SOLD_DAILY_TYPEWISE ; create or replace table eggozdb.maplemonk.egg_movement_ims as select pp.grn_date, pp.processing_egg_count,zone_name, pp.warehouse,procurement_egg_tray,eggqualitycheck_egg_loss, et.received_eggs_ims ,et.sent_eggs_ims*-1 as sent_eggs_ims, ps.eggs_sold,ub_sold_eggs, ps.eggs_return,eggs_promo from ( select grn_date,zone_name, processing_egg_count, warehouse,sum(procurement_egg_tray) procurement_egg_tray,sum(eggqualitycheck_egg_loss) eggqualitycheck_egg_loss from eggozdb.maplemonk.batch_procurement_processing_packaging group by warehouse,grn_date,processing_egg_count,zone_name)pp left join( select beat_date,to_warehouse,sum(sent_eggs_ims),sum(received_eggs_ims) received_eggs_ims,sum(sent_eggs_ims) sent_eggs_ims from eggozdb.maplemonk.epc_dc_transfer group by beat_date,to_warehouse)et on pp.warehouse=et.to_warehouse and pp.grn_date = et.beat_date left join( select loading_point,date,sum(eggs_sold) eggs_sold, sum(eggs_promo) eggs_promo, sum(eggs_return) eggs_return from primary_and_secondary_sku where sale_type=\'Primary_sale\' group by loading_point,date) ps on pp.grn_date=ps.date and pp.warehouse=ps.loading_point left join( select delivery_date,region,sum(eggs_sold_daily_typewise) ub_sold_eggs from ub_log group by region,delivery_date ) ub on pp.grn_date = ub.delivery_date and pp.zone_name = ub.region group by warehouse,grn_date,pp.processing_egg_count, zone_name, eggqualitycheck_egg_loss,eggs_sold,ub_sold_eggs, eggs_return,procurement_egg_tray,received_eggs_ims,sent_eggs_ims,ps.eggs_promo ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from EGGOZDB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            